func eventuallyConsistentGet(ctx context.Context, key client.ObjectKey, obj client.Object) {
    Eventually(func() bool {
        err := k8sClient.Get(ctx, key, obj)
        return err == nil
    }, time.Minute, time.Second).Should(BeTrue())
}

